WITH (autovacuum_analyze_scale_factor='0.01', autovacuum_vacuum_scale_factor='0.05')
--;;
CREATE TABLE IF NOT EXISTS raw_shopify_products (
    id bigint NOT NULL,
    organization_id character varying(64),
    admin_graphql_api_id text,
    title text,
    handle text,
    status text,
    vendor text,
    product_type text,
    tags text,
    image jsonb,
    images jsonb,
    variants jsonb,
    options jsonb,
    created_at timestamp with time zone,
    updated_at timestamp with time zone,
    __hevo__marked_deleted boolean DEFAULT false
)
--;;
CREATE TABLE IF NOT EXISTS raw_shopify_refunds (
    id bigint NOT NULL,
    order_id bigint,
    created_at timestamp without time zone,
    note text,
    user_id bigint,
    processed_at timestamp without time zone,
    duties json,
    order_adjustments json,
    admin_graphql_api_id character varying(512),
    restock boolean,
    total_duties_set json,
    organization_id character varying(512) NOT NULL,
    source_type character varying(512),
    __hevo__ingested_at bigint,
    __hevo__marked_deleted boolean,
    date_start timestamp without time zone
)
--;;
CREATE TABLE IF NOT EXISTS refund_lines (
    id bigint NOT NULL,
    source_type character varying(100) NOT NULL,
    quantity integer,
    subtotal_amount numeric,
    total_tax numeric,
    order_lines_id bigint,
    order_id bigint,
    refund_id bigint,
    organization_id character varying(100) NOT NULL,
    created_at timestamp without time zone,
    product_id character varying(255),
    product_name character varying(255),
    city character varying(100),
    discount_code character varying(100),
    state character varying(100),
    zip character varying(100),
    product_full_url text,
    customer_name text,
    order_status_url text,
    updated_at timestamp without time zone,
    last_synced timestamp without time zone
)
--;;
CREATE TABLE IF NOT EXISTS refunds (
    refund_id bigint NOT NULL,
    source_type character varying(100) NOT NULL,
    order_id bigint,
    refund_date timestamp without time zone,
    refund_amount numeric,
    shipping_refund numeric,
    created_at timestamp without time zone,
    updated_at timestamp without time zone,
    city character varying(255),
    product_id character varying(255),
    product_name character varying(255),
    last_synced timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    organization_id character varying(100) NOT NULL,
    kind character varying(100),
    discount_code character varying(100),
    state character varying(100),
    zip character varying(100),
    product_full_url text,
    customer_name text,
    order_status_url text,
    shipping_refund_tax numeric(14,2)
)
--;;
CREATE TABLE IF NOT EXISTS shipment_scans (
    organization_id character varying(100) NOT NULL,
    waybill character varying(255) NOT NULL,
    source_type character varying(100) DEFAULT 'delhivery'::character varying NOT NULL,
    scan_datetime timestamp without time zone NOT NULL,
    scan_status character varying(255),
    status_code character varying(100) NOT NULL,
    scanned_location character varying(255),
    instructions text,
    activity_description text,
    created_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP
)
--;;
CREATE TABLE IF NOT EXISTS shipments (
    organization_id character varying(100) NOT NULL,
    waybill character varying(255) NOT NULL,
    order_id character varying(255),
    source_type character varying(100) NOT NULL,
    aggregator character varying(100),
    reference_no character varying(255),
    pickup_location character varying(255),
    pickup_date timestamp without time zone,
    expected_delivery_date timestamp without time zone,
    delivery_date timestamp without time zone,
    current_status character varying(255),
    status_code character varying(100),
    consignee_name character varying(255),
    consignee_city character varying(100),
    consignee_state character varying(100),
    consignee_pincode character varying(20),
    sender_name character varying(255),
    origin character varying(255),
    destination character varying(255),
    invoice_amount numeric(14,2),
    cod_amount numeric(14,2),
    weight numeric(10,3),
    zone character varying(10),
    created_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    updated_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP
)
